fn solve(n: i8) -> i8 {
    // For positive n, integer division n/2 truncates toward zero,
    // which matches floor(n/2) when n > 0.
    if n % 2 == 0 {
        // Even case: result = n/2
        n / 2
    } else {
        // Odd case: result = (n/2) - n
        n / 2 - n
    }
}

