        assert_eq!(solve(3), -2);   // -1 + 2 - 3 = -2
        assert_eq!(solve(4), 2);    // -1 + 2 - 3 + 4 = 2
        assert_eq!(solve(5), -3);   // -1 + 2 - 3 + 4 - 5 = -3
        assert_eq!(solve(6), 3);    // ... = 3
